# ingest

Terraform for the ingest pipeline: a landing bucket, an event queue, and a checkpoint table.

Today an engineer runs `terraform apply` from a laptop. The `platform/ingest` repository's GitHub
Actions workflow is meant to take that over, running `plan` on pull requests and `apply` on merges
to `main`.
resource "aws_s3_bucket" "landing" {
  bucket = "ingest-landing-staging"
}

resource "aws_sqs_queue" "events" {
  name = "ingest-events-staging"
}

resource "aws_dynamodb_table" "checkpoints" {
  name         = "ingest-checkpoints-staging"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "source"

  attribute {
    name = "source"
    type = "S"
  }
}
provider "aws" {
  region = "eu-north-1"
}
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }

  backend "s3" {
    bucket       = "ingest-terraform-state"
    key          = "ingest/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}

